-- 新作业动作沿用 CUSTOMER 数据范围；普通角色不自动获权。
SET @work_app=(SELECT id FROM iam_application WHERE app_code='SUPPLY_CHAIN');
SET @work_parent=(SELECT id FROM iam_resource WHERE permission_code='crm:pool:private-read' AND application_id=@work_app);
INSERT INTO iam_resource(id,application_id,parent_id,resource_code,resource_type,permission_code,display_name,sort_order,status,created_at,updated_at) VALUES(UUID_TO_BIN('31c7b1ae-5bf5-49df-8284-4489c44e2682'),@work_app,@work_parent,'SUPPLY_CHAIN.ACTION.CRM_STORE_VISIT_WRITE','BUTTON','crm:store:visit-write','门店拜访',20,'ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6));
INSERT INTO iam_resource(id,application_id,parent_id,resource_code,resource_type,permission_code,display_name,sort_order,status,created_at,updated_at) VALUES(UUID_TO_BIN('32c7b1ae-5bf5-49df-8284-4489c44e2682'),@work_app,@work_parent,'SUPPLY_CHAIN.ACTION.CRM_STORE_VISIT_REVIEW','BUTTON','crm:store:visit-review','核验与撤销拜访',21,'ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6));
INSERT INTO iam_resource(id,application_id,parent_id,resource_code,resource_type,permission_code,display_name,sort_order,status,created_at,updated_at) VALUES(UUID_TO_BIN('33c7b1ae-5bf5-49df-8284-4489c44e2682'),@work_app,@work_parent,'SUPPLY_CHAIN.ACTION.CRM_STORE_ORDER_WRITE','BUTTON','crm:store:order-write','门店开单',22,'ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6));
INSERT IGNORE INTO iam_package_resource(package_version_id,resource_id,created_at) SELECT DISTINCT p.package_version_id,r.id,UTC_TIMESTAMP(6) FROM iam_package_resource p JOIN iam_resource r ON r.id IN (UUID_TO_BIN('31c7b1ae-5bf5-49df-8284-4489c44e2682'),UUID_TO_BIN('32c7b1ae-5bf5-49df-8284-4489c44e2682'),UUID_TO_BIN('33c7b1ae-5bf5-49df-8284-4489c44e2682')) WHERE p.resource_id=@work_parent;
INSERT INTO iam_app_menu_node(tenant_id,application_id,id,parent_id,resource_id,node_type,display_name,sort_order,visible,status,created_at,updated_at) SELECT n.tenant_id,n.application_id,r.id,n.id,r.id,'BUTTON',r.display_name,r.sort_order,FALSE,'ACTIVE',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6) FROM iam_app_menu_node n JOIN iam_resource r ON r.id IN (UUID_TO_BIN('31c7b1ae-5bf5-49df-8284-4489c44e2682'),UUID_TO_BIN('32c7b1ae-5bf5-49df-8284-4489c44e2682'),UUID_TO_BIN('33c7b1ae-5bf5-49df-8284-4489c44e2682')) WHERE n.resource_id=@work_parent AND n.deleted_at IS NULL;
UPDATE iam_app_settings SET version=version+1,updated_at=UTC_TIMESTAMP(6) WHERE application_id=@work_app;
UPDATE iam_tenant t SET policy_version=policy_version+1,version=version+1,updated_at=UTC_TIMESTAMP(6) WHERE EXISTS(SELECT 1 FROM iam_app_menu_node n WHERE n.tenant_id=t.id AND n.resource_id=@work_parent AND n.deleted_at IS NULL);
